function pslcPort():int{$s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);$name=(string)stream_socket_get_name($s,false);fclose($s);return(int)substr($name,strrpos($name,':')+1);}function pslcRequest(int$port,string$method,string$path,string$body='',string$cookie=''):array{$s=stream_socket_client("tcp://127.0.0.1:$port",$e,$m,3);$head="$method $path HTTP/1.1\r\nHost: 127.0.0.1:$port\r\nConnection: close\r\n".($cookie===''?'':"Cookie: $cookie\r\n").($body===''?'':"Content-Type: application/x-www-form-urlencoded\r\n").'Content-Length: '.strlen($body)."\r\n\r\n";fwrite($s,$head.$body);$raw=(string)stream_get_contents($s);fclose($s);[$headers,$bytes]=array_pad(explode("\r\n\r\n",$raw,2),2,'');preg_match('#^HTTP/1\.1 ([0-9]{3})#',$headers,$status);$map=[];foreach(array_slice(explode("\r\n",$headers),1)as$line){$at=strpos($line,':');if($at!==false)$map[strtolower(substr($line,0,$at))][]=ltrim(substr($line,$at+1));}return[(int)($status[1]??0),$map,$bytes];}function pslcCookie(array$headers):array{$raw=$headers['set-cookie'][0]??'';if(preg_match('/^(fm2auth_[0-9]+)=([A-Za-z0-9,-]{16,128})(?:;|$)/',$raw,$m)!==1)throw new TestFailure('SETUP_FAILURE: cookie');return[$m[1],$m[2]];}function pslcCsrf(string$body):string{if(preg_match('/name="csrfToken" value="([0-9a-f]{64})"/',$body,$m)!==1)throw new TestFailure('SETUP_FAILURE: csrf');return$m[1];}
$db=new mysqli(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root',getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local',getenv('FMONITOR_TEST_DB_NAME')?:'fmonitor2_test',(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306));$db->set_charset('utf8mb4');$token=bin2hex(random_bytes(8));$prefix='pslc_'.$token.'_';$root=sys_get_temp_dir().'/fmonitor2-session-storage-tests/task-'.$token;$server=null;$tables=['fm2_pilot_auth_attempts','fm2_pilot_auth_credentials','fm2_pilot_users'];$remove=function(string$p)use(&$remove):void{if(is_file($p)||is_link($p)){unlink($p);return;}if(!is_dir($p))return;foreach(scandir($p)?:[]as$e)if($e!=='.'&&$e!=='..')$remove($p.'/'.$e);rmdir($p);};
try{mkdir($root,0700,true);$db->query("CREATE TABLE `{$prefix}fm2_pilot_users`(user_id BIGINT PRIMARY KEY,email VARCHAR(255) NOT NULL,full_name VARCHAR(255) NOT NULL,status TINYINT NOT NULL,activation_state VARCHAR(32) NOT NULL)");$db->query("CREATE TABLE `{$prefix}fm2_pilot_auth_credentials`(user_id BIGINT PRIMARY KEY,email_normalized VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NULL)");$db->query("CREATE TABLE `{$prefix}fm2_pilot_auth_attempts`(id BIGINT AUTO_INCREMENT PRIMARY KEY,email_normalized VARCHAR(255) NOT NULL,succeeded TINYINT NOT NULL,attempted_at DATETIME(6) NOT NULL)");$email='canonical.auth@shlz.ru';$password='Correct fixture password 2026';$hash=password_hash($password,PASSWORD_ARGON2ID);$db->query("INSERT INTO `{$prefix}fm2_pilot_users` VALUES(17,'$email','Canonical Actor',1,'active')");$q=$db->prepare("INSERT INTO `{$prefix}fm2_pilot_auth_credentials` VALUES(17,?,?)");$q->bind_param('ss',$email,$hash);$q->execute();$port=pslcPort();$env=array_replace($_ENV,['FMONITOR_DB_HOST'=>getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1','FMONITOR_DB_PORT'=>getenv('FMONITOR_TEST_DB_PORT')?:'23306','FMONITOR_DB_NAME'=>getenv('FMONITOR_TEST_DB_NAME')?:'fmonitor2_test','FMONITOR_DB_USER'=>getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root','FMONITOR_DB_PASSWORD'=>getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local','FMONITOR_PROCESS_TABLE_PREFIX'=>$prefix,'FMONITOR_SESSION_STATE_ROOT'=>$root,'FMONITOR_SESSION_INSTANCE'=>'local_auth_v10','FMONITOR_TRUSTED_REQUEST_SCHEME'=>'http']);$process=proc_open([PHP_BINARY,'-S',"127.0.0.1:$port",dirname(__DIR__,2).'/rapid-pilot/router.php'],[1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2),$env);$server=[$process,$pipes];$deadline=microtime(true)+3;do{usleep(20000);$s=@stream_socket_client("tcp://127.0.0.1:$port",$e,$m,.1);if(is_resource($s)){fclose($s);break;}}while(microtime(true)<$deadline);[$status,$headers,$body]=pslcRequest($port,'GET','/pilot/login');assertSameValue(200,$status,'INTENTIONAL_RED: canonical anonymous LocalAuth GET');[$cookieName,$oldId]=pslcCookie($headers);$csrf=pslcCsrf($body);$oldBytes=(string)file_get_contents($root.'/sessions/local_auth_v10/s-'.$oldId.'.session');$oldState=unserialize($oldBytes,['allowed_classes'=>false]);assertSameValue($oldBytes,serialize($oldState),'anonymous payload byte-canonical');assertSameValue($csrf,$oldState['auth_csrf']??null,'anonymous CSRF committed');$login=http_build_query(['csrfToken'=>$csrf,'email'=>$email,'password'=>$password]);[$loginStatus,$loginHeaders]=pslcRequest($port,'POST','/pilot/login',$login,"$cookieName=$oldId");assertSameValue(303,$loginStatus,'canonical login regenerates');[, $newId]=pslcCookie($loginHeaders);$newBytes=(string)file_get_contents($root.'/sessions/local_auth_v10/s-'.$newId.'.session');$newState=unserialize($newBytes,['allowed_classes'=>false]);assertSameValue($newBytes,serialize($newState),'authenticated payload byte-canonical');assertSameValue([17,$email],[$newState['auth_user_id']??null,$newState['auth_email']??null],'authenticated canonical identity');echo"PASS: PILOT-SESSION-STORAGE-001 v10 LocalAuth canonical payloads\n";}finally{if(is_array($server)){[$process,$pipes]=$server;if(is_resource($process)&&proc_get_status($process)['running'])proc_terminate($process,9);foreach($pipes as$p)if(is_resource($p))fclose($p);if(is_resource($process))proc_close($process);}foreach($tables as$table)$db->query("DROP TABLE IF EXISTS `{$prefix}{$table}`");$db->close();$remove($root);$parent=dirname($root);if(is_dir($parent)&&count(scandir($parent)?:[])===2)rmdir($parent);}
